patch:
diff --git a/src/dbg.ts b/src/dbg.ts
new file mode 100644
index 0000000..608d074
--- /dev/null
+++ b/src/dbg.ts
@@ -0,0 +1,29 @@
+import nock from "nock";
+
+nock.disableNetConnect();
+nock("https://maps.googleapis.com")
+  .get(
+    "/maps/api/place/details/json?fields=place_id,name&key=foo&place_id=notarealid"
+  )
+  .reply(200, JSON.stringify({ status: "NOT_FOUND" }), {
+    "Content-Type": "application/json",
+  });
+
+import { Client } from "./client";
+
+(async () => {
+  const client = new Client();
+  try {
+    const r = await client.placeDetails({
+      params: { place_id: "notarealid", key: "foo", fields: ["place_id", "name"] },
+    });
+    console.log("RESOLVED; validateStatus:", String(r.config.validateStatus).slice(0, 300));
+    console.log("response status:", r.status, "data:", r.data);
+  } catch (e) {
+    console.log("REJECTED:", (e as Error).message, (e as any).code);
+  }
+  process.exit(0);
+})().catch((e) => {
+  console.log("ERR", e);
+  process.exit(1);
+});
